CREATE TABLE tool_registry_snapshots(id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload))) STRICT;
CREATE TABLE tool_definitions(tool_id TEXT NOT NULL, version TEXT NOT NULL, definition_hash TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(tool_id,version)) STRICT;
CREATE TABLE tool_instances(id TEXT PRIMARY KEY, tool_id TEXT NOT NULL, version TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload)), FOREIGN KEY(tool_id,version) REFERENCES tool_definitions(tool_id,version)) STRICT;
CREATE TABLE tool_batches(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), registry_snapshot_id TEXT NOT NULL REFERENCES tool_registry_snapshots(id), state TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload))) STRICT;
CREATE TABLE tool_calls(id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES tool_batches(id), ordinal INTEGER NOT NULL CHECK(ordinal>0), operation_id TEXT UNIQUE REFERENCES operations(id), payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(batch_id,ordinal)) STRICT;
CREATE TABLE tool_pins(owner_kind TEXT NOT NULL CHECK(owner_kind IN('workspace','session')), owner_id TEXT NOT NULL, tool_id TEXT NOT NULL, version TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(owner_kind,owner_id,tool_id), FOREIGN KEY(tool_id,version) REFERENCES tool_definitions(tool_id,version)) STRICT;
CREATE TABLE agent_terminals(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), payload TEXT NOT NULL CHECK(json_valid(payload)), output_start INTEGER NOT NULL CHECK(output_start>=0), output_end INTEGER NOT NULL CHECK(output_end>=output_start)) STRICT;
CREATE TABLE terminal_output_segments(terminal_id TEXT NOT NULL REFERENCES agent_terminals(id), start_offset INTEGER NOT NULL, next_offset INTEGER NOT NULL CHECK(next_offset>start_offset), artifact_id TEXT NOT NULL REFERENCES artifacts(id), PRIMARY KEY(terminal_id,start_offset)) STRICT;
